package dev.localtype.keyboard


/** Exclusions shared by the bundled-list check and neural suggestions; words stay out of source. */
object SuggestionWordRules {
    /**
     * Matches the list scan's whole entry and the individual words of a hyphenated compound. [EXCLUDED_HASHES]
     * apply in every language, since English slurs turn up in other languages' subtitles too; a language adds
     * its own ([forLanguage]).
     */
    fun isExcluded(word: String, language: LanguageProfile = LanguageProfile.ENGLISH): Boolean {
        val normalized = AdaptiveNgramModel.normalize(word)
        val own = forLanguage(language)
        return (listOf(normalized) + normalized.split(' ', '-')).any { sha256(it).let { hash -> hash in EXCLUDED_HASHES || hash in own } }
    }

    /** The language's own exclusions, beyond [EXCLUDED_HASHES]. */
    fun forLanguage(language: LanguageProfile): Set<String> = when (language.code) {
        LanguageProfile.SPANISH.code -> EXCLUDED_HASHES_ES
        LanguageProfile.PORTUGUESE.code -> EXCLUDED_HASHES_PT
        LanguageProfile.HEBREW.code -> EXCLUDED_HASHES_HE
        LanguageProfile.ARABIC.code -> EXCLUDED_HASHES_AR
        LanguageProfile.PERSIAN.code -> EXCLUDED_HASHES_FA
        LanguageProfile.GALICIAN.code -> EXCLUDED_HASHES_GL
        else -> emptySet()
    }

    private fun sha256(word: String): String {
        val digest = dev.localtype.keyboard.sha256(word.encodeToByteArray())
        val hex = "0123456789abcdef"
        return buildString(64) {
            digest.forEach { byte ->
                val value = byte.toInt() and 0xff
                append(hex[value ushr 4])
                append(hex[value and 15])
            }
        }
    }

